# key_usage_summary.py - Summarize key usage and crypto events\n\nimport json\nfrom collections import Counter\n\n# ---------------------------------------------------------------------------\n# Model for a single crypto event (used for demo purposes)\n# ---------------------------------------------------------------------------\n\nclass CryptoEvent:\n    def __init__(self, operation: str, key_id: str, timestamp: str):\n        self.operation = operation    # e.g., 'encrypt', 'decrypt', 'sign', 'verify'\n        self.key_id = key_id\n        self.timestamp = timestamp   # ISO8601 string\n\n# ---------------------------------------------------------------------------\n# Simple in‑memory store (replace with persistent store or DB in production)\n# ---------------------------------------------------------------------------\n\nevents_store = []\n\ndef record_event(event: CryptoEvent):\n    \"\"\"Record a crypto operation for later summarisation.\"\"\"\n    events_store.append(event)\n\ndef load_events() -> list[CryptoEvent]:\n    \"\"\"Load persisted events – placeholder implementation.\"\"\"\n    # In a real system you would read from a database or log store\n    return events_store\n\n# ---------------------------------------------------------------------------\n# Summarisation logic\n# ---------------------------------------------------------------------------\n\ndef summarize_usage() -> dict:\n    \"\"\"Return a summary dict:\n    {\n        'total_events': int,\n        'by_operation': {operation: count, ...},\n        'by_key': {key_id: count, ...},\n        'most_used_key': str,\n    }\n    \"\"\"\n    all_events = load_events()\n    total = len(all_events)\n    by_operation = Counter(e.operation for e in all_events)\n    by_key = Counter(e.key_id for e in all_events)\n    most_key_id, most_count = by_key.most_common(1)[0] if by_key else (None, 0)\n    return {\n        'total_events': total,\n        'by_operation': dict(by_operation),\n        'by_key': dict(by_key),\n        'most_used_key': most_key_id,\n        'most_used_key_count': most_count,\n    }\n\n# ---------------------------------------------------------------------------\n# CLI helper for quick view\n# ---------------------------------------------------------------------------\n\ndef main():\n    summary = summarize_usage()\n    print(json.dumps(summary, indent=2))\n\nif __name__ == '__main__':\n    main()\n